import { ClubStore } from './club-store.js';
import { modes, skills, player, activeMatch, nextGroup, eligible, estimateWait, mixerStandings, busyPlayers } from './engine.js';
import { formats, divisions, standings } from './tournament.js';
import { scoreCall, serviceCourt, gamePoint } from './scoring.js';
import { escapeHTML as esc, icon, button as btn, picker, field, stepper, initials, formatDate, contrastText, setupComponents } from './components.js';

const store = new ClubStore();
const main = document.querySelector('#main'), dialog = document.querySelector('#sheet');
let mode = 'open', tab = 'courts', scoringId = null, round = 1, bracketSection = 'Winners', toastTimer, search = '';
let lastFocus = null;
let poolFilter='all', roundFilter='all';
const s = () => store.state;
const organizer = () => store.role === 'organizer';
const modeIcon = { open: 'court', tournament: 'trophy', mixer: 'people', challenge: 'bolt' };
const stateLabel = { available: 'Available', called: 'Called', playing: 'In play', reserved: 'Reserved', closed: 'Closed', assigned: 'Assigned', final: 'Final', ready: 'Ready', waiting: 'Waiting', bye: 'Bye', void: 'Not needed', cancelled: 'Cancelled' };
const badge = status => `<span class="badge ${status}">${esc(stateLabel[status] || status)}</span>`;
const empty = (title, detail, action = '') => `<div class="empty">${icon('court')}<h3>${title}</h3><p>${detail}</p>${action}</div>`;
function notify(message, error = false) { const toast = document.querySelector('#toast'); toast.textContent = message; toast.className = `show ${error ? 'is-error' : ''}`; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), error ? 10000 : 4500); }
function go(nextMode, nextTab = 'courts') { location.hash = `${nextMode}/${nextTab}`; }
function readRoute() {
  const [m, t] = location.hash.slice(1).split('/');
  mode = modes[m] || m === 'display' ? m : 'open';
  const tabs = tabsFor(mode); tab = tabs.some(([id]) => id === t) ? t : tabs[0]?.[0] || 'courts'; render();
}
function tabsFor(m) {
  return m === 'tournament' ? [['matches','Matches'],['bracket','Bracket'],['standings','Standings'],['entries','Entrants']]
    : m === 'mixer' ? [['roster','Roster'],['standings','Standings'],['courts','Courts'],['results','Results']]
    : m === 'challenge' ? [['courts','Courts'],['queue','Queue'],['results','Results']] : [['courts','Courts'],['queue','Queue'],['history','History']];
}
function navItems(mobile = false) {
  return Object.entries(modes).map(([key, label]) => `<a href="#${key}/${tabsFor(key)[0][0]}" ${mode === key ? 'aria-current="page"' : ''} aria-label="${label}">${icon(modeIcon[key])}<span>${mobile ? ({mixer:'Mixer',challenge:'Challenge'}[key] || label) : label}</span></a>`).join('');
}
function renderHeader() {
  document.querySelector('#header').innerHTML = `<div class="topbar"><a class="brand" href="#open/courts" aria-label="Dill Next clubhouse">${s().settings.logo?`<img class="club-brand-logo" src="${esc(s().settings.logo)}" alt="Club logo">`:`<span class="brand-mark">${icon('court')}</span>`}<span>${esc(s().settings.name||"Dill Next")}<small>${esc(s().settings.tagline||"YOUR COURT. YOUR COMMUNITY.")}</small></span></a><div class="top-actions">${store.platformClub?`<a class="btn quiet club-home-link" href="./${store.live?"?live=1":"?live=0"}#manage/${store.clubId}">${icon("people")}<span>Members</span></a>`:`<a class="btn quiet club-home-link" href="./">Website</a>`}<span class="connection ${store.live ? 'live' : ''}" title="${esc(store.status)}">${store.live ? icon('check') : icon('ball')}<span>${store.live ? (store.status.startsWith('Live') ? 'Live club' : store.role === 'visitor' ? 'Connect your club' : 'Reconnecting') : 'Clubhouse'}</span></span>${btn(icon('monitor')+'<span>Court display</span>','display','','quiet desktop-label')}${btn(icon('settings'),'settings','aria-label="Club settings"','icon-btn')}${btn(organizer() ? initials('Club Organizer') : icon('people'), 'account', 'aria-label="Account and sign in"', 'avatar-btn')}</div></div><div class="nav-wrap"><nav class="mode-nav" aria-label="Play modes">${navItems()}</nav><span class="nav-note">${icon('clock')} Philippine time <span class="local-time">${new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'}).format(new Date())}</span></span></div>`;
  document.querySelector('#mobile-nav').innerHTML = navItems(true);
  document.body.classList.toggle('display-mode', mode === 'display' || store.role === 'display');
}
function render() {
  document.documentElement.style.setProperty('--accent', s().settings.accent);
  document.documentElement.style.setProperty('--on-accent', contrastText(s().settings.accent));
  renderHeader();
  if (store.role === 'display' || mode === 'display') { main.innerHTML = displayView(); return; }
  if (['guest','member'].includes(store.role)) { document.body.classList.add('player-mode'); main.innerHTML = guestView() + (store.role==='member'?`<section class="member-courts"><h2>Club court board</h2><div class="court-grid">${s().courts.map(c=>courtCard(c,true)).join('')}</div></section>`:''); return; } document.body.classList.remove('player-mode');
  if (store.role === 'visitor') { main.innerHTML = `<section class="welcome"><span class="eyebrow">WELCOME TO YOUR CLUBHOUSE</span><h1>Good games start here.</h1><p>Sign in with an approved club account. A membership invitation is a request; the owner must accept it before you can access the club.</p>${btn('Go to player account','account','','primary')}${btn('Explore the clubhouse','demo','','quiet')}<p class="muted">The club owner and vice owners manage courts and games. Day visitors use the separate Open Play QR.</p></section>`; return; }
  const activeCount = s().courts.filter(c => c.matchId).length;
  const count = mode === 'open' ? s().open.length : mode === 'mixer' ? s().mixer.length : mode === 'challenge' ? s().challenge.length : s().tournament?.entrants.length || 0;
  main.innerHTML = `<section class="page-heading"><div><div class="eyebrow">THE CLUBHOUSE <span>/ ${esc(modes[mode])}</span></div><h1>${esc(modes[mode])}<span class="heading-dot">.</span></h1><p>${{open:'Less waiting. More playing. Let’s get you on court.',tournament:'Every match matters. Make your run to the final.',mixer:'New partners. Good rallies. Everyone gets a game.',challenge:'Hold your court. Take on the next challengers.'}[mode]}</p></div><div class="heading-actions">${btn(icon('qr')+' Check-in QR','share','','secondary')}${btn(icon('plus') + (mode==='tournament'?' New event':mode==='challenge'?' Add pair':' Add player'), mode==='tournament'?'new-event':mode==='challenge'?'add-pair':'add-player','','primary')}</div></section>
    <section class="session-banner"><div class="session-copy"><span class="eyebrow">CLUB SESSION</span><h2>${esc(mode==='tournament'&&s().tournament?s().tournament.name:s().session.title)}</h2><p>${icon('calendar')}${new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',weekday:'long',month:'long',day:'numeric'}).format(new Date())}<span class="session-tag">${mode==='open'?(s().settings.openSize===4?'Doubles':'Singles'):mode==='tournament'?(formats[s().tournament?.format]||'Registration'):mode==='mixer'?'Rotating doubles':`Winner stays · ${s().settings.challengeLimit}-win limit`}</span></p></div><div class="banner-stats"><div><strong>${activeCount}<span>/${s().courts.length}</span></strong><small>courts occupied</small></div><div><strong>${count}</strong><small>${mode==='challenge'?'pairs checked in':mode==='tournament'?'entrants':'players checked in'}</small></div><div class="court-motif" aria-hidden="true"><i></i><span></span></div></div></section>
    <div class="section-bar"><nav class="section-tabs" aria-label="${esc(modes[mode])} sections">${tabsFor(mode).map(([id,label])=>`<a href="#${mode}/${id}" ${tab===id?'aria-current="page"':''}>${label}${id==='queue'?` <span>${eligible(s(),mode==='challenge'?'challenge':'open').length}</span>`:''}</a>`).join('')}</nav><span class="save-state">${icon('check')}${store.live?'Changes sync live':'Changes saved'}</span></div>
    ${mode==='tournament'?tournamentView():mode==='mixer'?mixerView():['history','results'].includes(tab)?historyView(mode):tab==='queue'?queueView(mode==='challenge'?'challenge':'open'):courtWorkspace()}
    <footer class="page-footer"><span>Dill Next <span class="muted">· A place to play. A community to stay.</span></span><span>${esc(store.status)}</span></footer>`;
  if (scoringId && dialog.open) renderScoring(scoringId);
  if(mode==='tournament'&&tab==='bracket')requestAnimationFrame(drawBracketConnections);
}
function drawBracketConnections() {
  const board=main.querySelector('.bracket');if(!board||innerWidth<=650)return;
  board.querySelector('.bracket-connectors')?.remove();
  const bounds=board.getBoundingClientRect(), visible=new Map([...board.querySelectorAll('[data-match]')].map(el=>[el.dataset.match,el]));
  const paths=[];
  for(const m of s().matches){const dest=visible.get(m.id);if(!dest)continue;for(const source of m.sources||[]){const src=visible.get(source.match);if(!src)continue;
    const a=src.getBoundingClientRect(),b=dest.getBoundingClientRect(),x1=a.right-bounds.left+board.scrollLeft,y1=a.top+a.height/2-bounds.top,x2=b.left-bounds.left+board.scrollLeft,y2=b.top+b.height/2-bounds.top,mid=(x1+x2)/2;
    paths.push(`<path d="M${x1},${y1}H${mid}V${y2}H${x2}"/>`);
  }}
  board.insertAdjacentHTML('afterbegin',`<svg class="bracket-connectors" width="${board.scrollWidth}" height="${board.scrollHeight}" aria-hidden="true">${paths.join('')}</svg>`);
}
window.addEventListener('resize',()=>requestAnimationFrame(drawBracketConnections));
document.addEventListener('change',event=>{if(['poolFilter','roundFilter'].includes(event.target.name)){if(event.target.name==='poolFilter')poolFilter=event.target.value;else roundFilter=event.target.value;render();}});
function courtWorkspace() {
  const queueMode = mode==='challenge'?'challenge':'open';
  return `<div class="workspace"><section><div class="section-title"><h2>The courts <span class="count">${s().courts.length}</span></h2><span class="muted">Shared across all play modes</span></div><div class="court-grid">${s().courts.map(c=>courtCard(c)).join('')}</div><div class="club-note">${icon('ball')}<div><strong>A little court etiquette goes a long way.</strong><p>Be ready when you’re called. Celebrate a good rally. Welcome a new face.</p></div></div></section><aside class="queue-panel"><div class="section-title"><h2>${mode==='challenge'?'Next challengers':'Up next'}</h2><span class="count">${eligible(s(),queueMode).length} waiting</span></div>${queuePreview(queueMode)}</aside></div>`;
}
function courtCard(c, display = false) {
  const m=activeMatch(s(),c), score=m?.scoring?.points||m?.result||[0,0];
  const ready=m?.mode==='open'?s().open.filter(e=>m.sides.some(side=>side.playerIds.some(id=>e.playerIds.includes(id)))).reduce((n,e)=>n+e.readyIds.length,0):0;
  return `<article class="court-card ${c.status}" id="court-${c.id}"><div class="court-head"><span class="court-number">${icon('court')}${esc(c.name)}</span>${badge(c.status)}</div>${m?`<div class="match-meta"><span>${esc(modes[m.mode])}${m.label?' · '+esc(m.label):''}</span><span>${m.started?icon('clock')+' '+elapsed(m.started):m.mode==='open'?`${ready}/${m.sides.flatMap(side=>side.playerIds).length} ready`:'Ready to play'}</span></div><div class="court-teams">${m.sides.map((side,i)=>`<div class="team-row"><div class="avatar-stack">${side.playerIds.map((id,j)=>`<span class="avatar tone-${(i*2+j)%4}">${initials(player(s(),id)?.name||side.name)}</span>`).join('')}</div><div class="team-names">${side.playerIds.map(id=>`<strong>${esc(player(s(),id)?.name || side.name)}</strong>`).join('')}</div><span class="court-score ${m.scoring?.serving===i?'serving':''}">${score[i]}</span></div>${i===0?'<div class="versus"><span></span>VS<span></span></div>':''}`).join('')}</div>${m.scoring?`<p class="service-line">${icon('ball')}Serving ${esc(scoreCall(m.scoring))} · ${serviceCourt(m.scoring)} court</p>`:`<p class="service-line">${icon('people')}${m.mode==='open'?'Players, get your paddles ready.': 'Your court is reserved.'}</p>`}${!display&&organizer()?`<div class="court-actions">${btn(icon('play')+(m.scoring?' Continue scoring':' Score game'),'score',`data-id="${m.id}"`,'primary full')}${btn('Report final score','report',`data-id="${m.id}"`,'quiet full')}<details><summary>Match options</summary>${m.mode!=='tournament'&&m.mode!=='challenge'?btn('Finish without score','finish-without',`data-id="${m.id}"`,'quiet full'):''}${btn('Release / cancel call','release',`data-id="${m.id}"`,'quiet full')}${m.mode==='open'?btn('Mark a no-show','no-show',`data-id="${m.id}"`,'quiet full'):''}</details></div>`:''}`:`<div class="empty-court"><div class="court-drawing" aria-hidden="true"><i></i></div><h3>${c.status==='closed'?'Taking a breather':'Room for a good game'}</h3><p>${c.status==='closed'?'Reopen when the court is ready.':'Pick up a paddle. You’re next.'}</p></div>${!display&&organizer()?`<div class="court-actions">${c.status==='available'?btn(icon('plus')+' '+(mode==='challenge'?'Start challenge':'Call next group'),mode==='challenge'?'challenge-start':'call-next',`data-court="${c.id}"`,'secondary full'):''}${btn(c.status==='closed'?'Reopen court':'Close court','court-toggle',`data-id="${c.id}" data-status="${c.status==='closed'?'available':'closed'}"`,'quiet full')}</div>`:''}`}</article>`;
}
function elapsed(value) { const min=Math.max(0,Math.floor((Date.now()-new Date(value))/60000)); return `${min} min`; }
function queuePreview(qmode) {
  const list=eligible(s(),qmode),group=qmode==='open'?nextGroup(s()):list.slice(0,2);
  return `<div class="next-group"><span class="eyebrow">${qmode==='open'?'NEXT ON COURT':'NEXT MATCHUP'}</span>${group.length?`<h3>${group.flatMap(e=>e.playerIds.map(id=>esc(player(s(),id)?.name.split(' ')[0]))).join(' <span>·</span> ')}</h3><p>${qmode==='open'?'Longest-waiting eligible players':'First in line gets the next challenge'}</p>`:'<p>Add eligible players to form the next group.</p>'}${btn(icon('play')+(qmode==='open'?' Call next':' Start challenge'),qmode==='open'?'call-next':'challenge-start',group.length&&(s().courts.some(c=>c.status==='available'))?'':'disabled','primary full')}</div><div class="queue-mini">${list.slice(0,5).map((e,i)=>`<div class="queue-mini-row"><span class="queue-position">${String(i+1).padStart(2,'0')}</span><span class="avatar tone-${i%4}">${initials(player(s(),e.playerIds[0])?.name||e.name)}</span><div><strong>${esc(e.name)}</strong><small>${esc(e.playerIds.map(id=>player(s(),id)?.skill).filter((v,i,a)=>a.indexOf(v)===i).join(' / '))}</small></div><span class="wait-time">${elapsed(e.arrived)}</span></div>`).join('')||'<p class="muted">The queue is clear. Ready for the next game?</p>'}</div><a class="view-link" href="#${mode}/queue">View full queue ${icon('people')}</a><div class="queue-tip">${icon('qr')}<div><strong>Skip the clipboard.</strong><p>Players can scan the session QR to check themselves in.</p>${btn('Share check-in','share','','quiet small')}</div></div>`;
}
function queueView(qmode) {
  const list=[...s()[qmode]].sort((a,b)=>a.arrived-b.arrived),waiting=eligible(s(),qmode);
  return `<section class="panel"><div class="section-title"><div><h2>${qmode==='challenge'?'Challenger queue':'Player queue'}</h2><p class="muted">Paused entries keep their arrival time. Partners stay together.</p></div>${btn(icon('play')+(qmode==='challenge'?' Start challenge':' Call next'),qmode==='challenge'?'challenge-start':'call-next','','primary')}</div>${qmode==='open'?`<div class="queue-controls"><div class="segmented" aria-label="Matching">${['mixed','same'].map(v=>btn(v==='mixed'?'Mixed skills':'Same skill','matching',`data-value="${v}" aria-pressed="${s().settings.matching===v}"`,s().settings.matching===v?'selected':'')).join('')}</div><span class="muted">${estimateWait(s())===null?'Wait estimates appear after 3 completed timed games.':`Estimated wait from ${estimateWait(s())} min`}</span></div>`:''}${qmode==='open'?`<div class="manual-stack"><div><strong>You control the stack.</strong><p>Choose entries below to call a specific group, or pair two waiting solo players. Partners are never split.</p></div>${btn('Call selected group','call-selected','','secondary')}${btn('Pair selected solos','pair-selected','','')}</div>`:''}<div class="queue-list">${list.map((e,i)=>`<article class="queue-row"><span class="queue-position">${String(i+1).padStart(2,'0')}</span>${qmode==='open'&&e.status==='waiting'?`<label class="stack-select"><input type="checkbox" name="stackEntry" value="${e.id}" aria-label="Select ${esc(e.name)}"></label>`:''}<div class="queue-person"><strong>${esc(e.name)}</strong><small>${esc(e.playerIds.map(id=>player(s(),id)?.skill).join(' · '))} · ${e.playerIds.some(id=>player(s(),id)?.source==='visitor')?'Visitor · ':e.playerIds.some(id=>player(s(),id)?.source==='member')?'Member · ':''} ${e.streak?`${e.streak} consecutive win${e.streak===1?'':'s'}`:elapsed(e.arrived)+' waiting'}</small></div>${badge(e.status)}<div class="row-actions">${['waiting','paused'].includes(e.status)?`${btn(e.status==='paused'?'Resume':'Pause','queue-action',`data-id="${e.id}" data-mode="${qmode}" data-value="${e.status==='paused'?'resume':'pause'}"`,'small')}${qmode==='open'&&e.playerIds.length===2?btn('Unpair','unpair',`data-id="${e.id}"`,'small quiet'):''}${btn('To back','queue-action',`data-id="${e.id}" data-mode="${qmode}" data-value="back"`,'small quiet')}${btn(icon('close'),'queue-action',`data-id="${e.id}" data-mode="${qmode}" data-value="remove" aria-label="Remove ${esc(e.name)}"`,'icon-btn quiet')}`:e.status==='called'?`${btn('Mark ready','ready-all',`data-id="${e.id}"`,'small')}`:''}</div></article>`).join('')||empty('A fresh court. A fresh queue.','Add players to get the next game going.',btn('Add player','add-player','','primary'))}</div></section>`;
}
function historyView(filter) {
  const games=s().matches.filter(m=>m.mode===filter&&m.status==='final').reverse();
  return `<section class="panel"><div class="section-title"><h2>${filter==='open'?'Open Play history':'Results'}</h2><span class="muted">${games.length} completed games</span></div>${games.length?`<div class="results-list">${games.map(m=>`<article class="result-row"><div><strong>${esc(m.sides[0].name)}</strong><span class="muted"> vs </span><strong>${esc(m.sides[1].name)}</strong><small>${formatDate(m.finished)}${m.round?' · Round '+m.round:''}</small></div><span class="result-score">${m.result?m.result.join(' – '):'Unscored'}</span>${badge('final')}</article>`).join('')}</div>`:empty('The first result is waiting.','Completed games will be saved here.')}</section>`;
}
function tournamentView() {
  const t=s().tournament;if(!t)return empty('Make it a tournament.','Set the format, invite your players, and let the games begin.',btn('Create tournament','new-event','','primary'));
  const matches=s().matches.filter(m=>m.eventId===t.id), remaining=matches.filter(m=>m.section==='Pool play'&&m.status!=='final').length;
  const meta=`<div class="event-summary"><div><h2>${esc(t.name)}</h2><p>${esc(t.division)} · ${esc(formats[t.format])} · To ${t.target}, win by ${t.margin}</p>${t.start?`<p>${icon('calendar')}${formatDate(t.start)}${t.end?' – '+formatDate(t.end):''} · Asia/Manila</p>`:''}</div>${t.status==='registration'?btn('Generate matches','generate-tournament','','primary'):badge('In progress')}</div>`;
  if(tab==='entries')return `<section class="panel">${meta}<div class="section-title"><h3>Entrants <span class="count">${t.entrants.length}/24</span></h3>${t.status==='registration'?btn(icon('plus')+' Register entrant','register','','secondary'):''}</div>${t.entrants.map((e,i)=>`<div class="queue-row"><span class="queue-position">${i+1}</span><div class="queue-person"><strong>${esc(e.name)}</strong><small>${e.playerIds.map(id=>esc(player(s(),id)?.name)).join(' & ')}</small></div>${e.pool?badge('Pool '+e.pool):''}${t.status==='registration'?btn(icon('close'),'remove-entrant',`data-id="${e.id}" aria-label="Remove ${esc(e.name)}"`,'icon-btn quiet'):''}</div>`).join('')||empty('Who’s in?','Register singles or doubles entrants. Each player can appear once.',btn('Register entrant','register','','primary'))}</section>`;
  if(tab==='standings')return `<section class="panel">${meta}${['round','pool','playoffs'].includes(t.format)?`${[...new Set(t.entrants.map(e=>e.pool).filter(Boolean))].map(pool=>`<h3>${t.format==='round'?'Overall standings':'Pool '+pool}</h3>${standingsTable(standings(t,matches,pool))}`).join('')}<p class="rules-note">Ranked by wins, point difference, then points scored. Registration order breaks remaining ties. Playoff results do not count toward pool standings.</p>${t.qualifiers?.length?`<h3>Playoff qualifiers</h3>${t.qualifiers.map(q=>`<div class="queue-row"><strong>Seed ${q.seed}</strong><span>${esc(t.entrants.find(e=>e.id===q.id)?.name)}</span><small>Pool ${q.pool} · finish ${q.finish}</small></div>`).join('')}<p class="rules-note">Qualifiers seeded by pool finish, win rate, point difference per game, points per game, then registration order.</p>`:''}`:empty('Follow the bracket.','Elimination tournaments determine the winner through their final match.',`<a class="btn primary" href="#tournament/bracket">Open bracket</a>`)}</section>`;
  if(t.status==='registration')return `<section class="panel">${meta}${empty('Build your starting lineup.','Add at least two entrants, then generate matches.',`<a class="btn primary" href="#tournament/entries">Manage entrants</a>`)}</section>`;
  if(tab==='bracket') {
    const sections=[...new Set(matches.map(m=>m.section))];if(!sections.includes(bracketSection))bracketSection=sections[0];
    const filtered=matches.filter(m=>m.section===bracketSection), rounds=[...new Set(filtered.map(m=>m.round))].sort((a,b)=>a-b);if(!rounds.includes(round))round=rounds[0];
    return `<section class="panel bracket-panel">${meta}<div class="bracket-toolbar"><div class="segmented">${sections.map(section=>btn(section,'bracket-section',`data-value="${section}" aria-pressed="${bracketSection===section}"`,bracketSection===section?'selected':'')).join('')}</div>${t.format==='playoffs'?`<p class="muted">${remaining?`${remaining} pool matches until playoff seeding`:'Pool play complete · playoffs seeded'}</p>`:''}</div><div class="mobile-round"><button class="btn" data-action="round-prev" ${round===rounds[0]?'disabled':''} aria-label="Previous round">‹</button><strong>Round ${round}</strong><button class="btn" data-action="round-next" ${round===rounds.at(-1)?'disabled':''} aria-label="Next round">›</button></div><div class="bracket">${rounds.map(r=>`<div class="bracket-round ${r===round?'current':''}"><h3>Round ${r}</h3><div class="round-matches">${filtered.filter(m=>m.round===r).map(m=>matchCard(m)).join('')}</div></div>`).join('')}</div></section>`;
  }
  return `<section class="panel">${meta}<div class="section-title"><h3>Match center</h3><span class="muted">${matches.filter(m=>m.status==='final').length} completed · ${matches.filter(m=>m.status==='ready').length} ready</span></div>${t.format==='playoffs'?`<p class="rules-note">${remaining?`${remaining} pool matches remain. The playoff bracket will be seeded automatically.`:'Playoff bracket seeded. Open Bracket to follow the qualifiers.'}</p>`:''}<div class="match-filters">${picker('poolFilter','Pool',[{value:'all',label:'All pools'},...[...new Set(matches.map(m=>m.pool).filter(Boolean))].map(p=>({value:p,label:'Pool '+p}))],poolFilter)}${picker('roundFilter','Round',[{value:'all',label:'All rounds'},...[...new Set(matches.map(m=>m.round))].sort((a,b)=>a-b).map(r=>({value:String(r),label:'Round '+r}))],roundFilter)}</div><div class="match-grid">${matches.filter(m=>!['bye','void'].includes(m.status)&&(poolFilter==='all'||m.pool===poolFilter)&&(roundFilter==='all'||String(m.round)===roundFilter)).map(matchCard).join('')||empty('No matches in this view.','Try another pool or round filter.')}</div></section>`;
}
function sourceLabel(m,i) { const source=m.sources?.[i];if(!source)return 'To be decided';if('entrant'in source)return 'Bye'; const parent=s().matches.find(g=>g.id===source.match);return `${source.outcome==='loser'?'Loser':'Winner'} of ${parent?.label||'previous match'}`; }
function matchCard(m) {
  return `<article class="match-card ${m.status}" data-match="${m.id}"><div class="row between"><strong class="match-label">${esc(m.label||'Match')}</strong>${badge(m.status)}</div>${m.sides.map((side,i)=>`<div class="bracket-side ${m.winner&&m.winner===side?.id?'won':''}"><span>${esc(side?.name||sourceLabel(m,i))}<small>${side&&m.sources?.[i]?.match?esc(sourceLabel(m,i)):''}</small></span><strong>${m.result?.[i]??'—'}</strong></div>`).join('')}${m.pool?`<small class="muted">Pool ${m.pool}</small>`:''}${organizer()?`<div class="match-buttons">${m.status==='ready'?btn('Assign court','assign',`data-id="${m.id}"`,'small secondary'):['assigned','playing'].includes(m.status)?btn('Score game','score',`data-id="${m.id}"`,'small primary'):m.status==='final'?btn('Edit score','edit-score',`data-id="${m.id}"`,'small quiet'):''}${m.status==='ready'||m.status==='assigned'?btn('Report final','report',`data-id="${m.id}"`,'small quiet'):''}${m.courtId?btn('Release court','release',`data-id="${m.id}"`,'small quiet'):''}</div>`:''}</article>`;
}
function standingsTable(rows, mixer = false) {
  return `<div class="table-scroll"><table><thead><tr><th scope="col">Rank</th><th scope="col">${mixer?'Player':'Entrant'}</th><th scope="col">Played</th><th scope="col">Wins</th>${mixer?'': '<th scope="col">+/−</th>'}<th scope="col">Points</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><span class="rank ${i===0?'first':''}">${i+1}</span></td><th scope="row">${esc(r.name)}</th><td>${r.played??r.games}</td><td>${r.wins}</td>${mixer?'':`<td>${r.diff>0?'+':''}${r.diff}</td>`}<td>${r.pf??r.points}</td></tr>`).join('')}</tbody></table></div>`;
}
function mixerView() {
  if(tab==='results')return historyView('mixer');
  if(tab==='standings')return `<section class="panel"><h2>Individual standings</h2><p class="muted">Ranked by wins, then points scored.</p>${standingsTable(mixerStandings(s()),true)}</section>`;
  if(tab==='courts')return `<section><div class="section-title"><h2>Mixer round ${s().round||'—'}</h2>${btn('Start next round','mixer-round','','primary')}</div><div class="court-grid">${s().courts.map(c=>courtCard(c)).join('')}</div></section>`;
  const busy=busyPlayers(s());return `<section class="panel"><div class="section-title"><div><h2>A new partner every round.</h2><p class="muted">Players with fewer games and recent sit-outs go first.</p></div>${btn('Start round','mixer-round','','primary')}</div>${s().mixer.map(e=>`<div class="queue-row"><span class="avatar">${initials(player(s(),e.playerId)?.name)}</span><div class="queue-person"><strong>${esc(player(s(),e.playerId)?.name)}</strong><small>${esc(player(s(),e.playerId)?.skill)}</small></div>${badge(e.paused?'Paused':busy.has(e.playerId)?'playing':'Sitting out')}${btn(e.paused?'Resume':'Pause','mixer-pause',`data-id="${e.playerId}" ${busy.has(e.playerId)?'disabled':''}`,'small')}</div>`).join('')||empty('Mix things up.','Add individual players to start a rotating doubles round.')}</section>`;
}
function displayView() {
  const t=s().tournament, matches=t?s().matches.filter(m=>m.eventId===t.id):[];
  return `<section class="display-heading"><div><span class="eyebrow">Dill Next · COURT DISPLAY</span><h1>See you on court.</h1></div><div class="display-clock">${new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'}).format(new Date())}<small>${esc(store.status)}</small></div></section><div class="court-grid display-courts">${s().courts.map(c=>courtCard(c,true)).join('')}</div><div class="display-bottom"><section class="panel"><h2>Up next</h2>${eligible(s()).slice(0,8).map((e,i)=>`<div class="queue-row"><span class="queue-position">${i+1}</span><strong>${esc(e.name)}</strong></div>`).join('')||'<p>No players waiting.</p>'}</section>${t?`<section class="panel"><h2>${esc(t.name)}</h2>${['round','pool','playoffs'].includes(t.format)?standingsTable(standings(t,matches)):matches.filter(m=>!['void','bye'].includes(m.status)).slice(-3).map(matchCard).join('')}</section>`:''}</div>${store.role!=='display'?'<a class="btn secondary" href="#open/courts">Return to clubhouse</a>':''}`;
}
function guestView() {
  const mine=s().open.find(e=>e.playerIds.includes(store.userId));
  const myMatch=s().matches.find(m=>m.courtId&&m.sides.some(side=>side.playerIds.includes(store.userId)));
  return `<section class="guest-welcome"><span class="eyebrow">${esc(s().settings.name)} · ${store.role==='member'?'MEMBER OPEN PLAY':'DAY VISITOR CHECK-IN'}</span><h1>${mine?'You’re in. Let’s play.':'Your next game starts here.'}</h1><p>${esc(s().session.title)}</p>${store.role==='guest'?'<p class="visitor-note">One-day Open Play · No regular account needed. This does not grant club membership.</p>':''}${mine?`<section class="panel"><h2>${esc(mine.name)}</h2>${badge(mine.status)}<p>${myMatch?`Head to ${esc(s().courts.find(c=>c.id===myMatch.courtId)?.name)}. Your group is waiting.`:'You’re in the queue. We’ll show your court here when you’re called.'}</p>${mine.status==='called'?btn('I’m ready','guest-ready','','primary full'):['waiting','paused'].includes(mine.status)?`${btn(mine.status==='paused'?'Resume my place':'Pause my place','guest-pause','','secondary')}${btn('Leave queue','guest-leave','','quiet')}`:''}</section>`:`<form id="guest-form" class="panel">${field('name','Your display name','text','','required maxlength="60" autocomplete="nickname"')}${picker('skill','Skill level',skills,'Intermediate')}${s().settings.openSize===4?field('partner','Partner’s name (optional)','text','','maxlength="60"'):''}<p class="muted">Your name and match details appear on the club board.</p><p class="form-error" role="alert"></p><button class="btn primary full" type="submit">Join Open Play</button></form>`}</section>${myMatch?courtCard(s().courts.find(c=>c.id===myMatch.courtId),true):''}`;
}

function openSheet(title, body, className = '') {
  lastFocus=document.activeElement; scoringId=null;dialog.className=className;
  document.querySelector('#sheet-content').innerHTML=`<div class="sheet-handle" aria-hidden="true"></div><div class="sheet-head"><div><span class="eyebrow">Dill Next</span><h2 id="sheet-title">${title}</h2></div>${btn(icon('close'),'close','aria-label="Close dialog"','icon-btn quiet')}</div>${body}`;
  if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');
}
function closeSheet() {dialog.close();scoringId=null;document.body.classList.remove('modal-open');lastFocus?.focus?.();}
function formSheet(title, id, fields, action='Save changes', extra='') {openSheet(title,`<form id="${id}" class="sheet-form">${fields}<p class="form-error" role="alert"></p><div class="sheet-footer">${extra}<button type="submit" class="btn primary">${action}</button></div></form>`);}
const playerOptions = (includeNone=false) => [...(includeNone?[{value:'',label:'No partner'}]:[]),...s().players.map(p=>({value:p.id,label:p.name}))];
function addPlayerSheet(pair = false) {
  const isTournament=mode==='tournament';
  const allowPartner=pair||(mode==='open'&&s().settings.openSize===4);
  formSheet(pair?'Check in a pair':'Add a player','add-player-form',`<div class="callout">${pair?'Create two player identities and keep them together in the queue.':'Register a new player or choose an existing club player below.'}</div>${field('name',pair?'First player’s name':'Display name','text','','required maxlength="60"')}${picker('skill','Skill level',skills,'Intermediate')}${allowPartner?field('partner',pair?'Second player’s name':'Partner’s name (optional)','text','',`${pair?'required ':''}maxlength="60"`):''}${pair?field('team','Pair name (optional)'):''}<input type="hidden" name="pair" value="${pair}"><input type="hidden" name="mode" value="${mode}">${s().players.length?`<details><summary>Use an existing player</summary>${picker('existing','Club player',playerOptions())}${allowPartner?picker('existingPartner','Existing partner',playerOptions(true),''):''}${btn(pair?'Check in pair':'Add existing player','add-existing','','secondary')}</details>`:''}`,isTournament?'Create player':'Add to '+(mode==='mixer'?'mixer':pair?'queue':'Open Play'));
}
function checkInSheet() {
  formSheet('Check in players','join-form',`${picker('first','Player',playerOptions())}${s().settings.openSize===4?picker('second','Partner',playerOptions(true),''):''}<input type="hidden" name="mode" value="open">`,'Check in');
}
function settingsSheet() { formSheet('Club settings','settings-form',`<div class="settings-tabs"><h3>Courts & play</h3></div>${stepper('courts','Number of courts',s().courts.length,1,8)}${picker('openSize','Open Play',[{value:4,label:'Doubles · four players'},{value:2,label:'Singles · two players'}],s().settings.openSize)}${picker('matching','Matchmaking',[{value:'mixed',label:'Mixed skills'},{value:'same',label:'Same skill'}],s().settings.matching)}${stepper('challengeLimit','Consecutive win limit',s().settings.challengeLimit,1,5)}<h3>Make the club yours</h3><accent-picker value="${s().settings.accent}"></accent-picker><details><summary>Account & connection</summary><p class="muted">Open your player account to manage your clubs and memberships.</p><a class="btn secondary" href="./${store.live?'?live=1':'?live=0'}#dashboard">My account</a></details>`); }
function eventSheet() { formSheet('Create a tournament','event-form',`${s().tournament?'<div class="callout">This replaces the active event after confirmation. Previous results are retained in the event archive.</div>':''}${field('name','Tournament name','text','Dill Next Cup','required maxlength="80"')}${picker('format','Format',Object.entries(formats).map(([value,label])=>({value,label})),'single')}${picker('division','Division',divisions,'Open doubles')}<div class="form-grid">${picker('target','Game target',[11,15,21].map(n=>({value:n,label:`${n} points`})),11)}${stepper('margin','Win margin',2,1,5)}</div><div class="pool-options">${stepper('pools','Pools (pool formats)',2,2,6)}${stepper('qualify','Qualifiers per pool (playoffs)',2,1,3)}</div><h3>Schedule <small class="muted">optional</small></h3><date-range></date-range>${s().tournament?'<label class="checkbox"><input type="checkbox" name="confirm" required> Replace the current event and retain its history</label>':''}`,'Create event'); }
function registerSheet() {
  const t=s().tournament;formSheet('Register entrant','register-form',`${field('name',t.division.includes('doubles')?'Team name':'Entry name (optional)')}${picker('first','First player',playerOptions())}${t.division.includes('doubles')?picker('second','Second player',playerOptions(),s().players[1]?.id):''}<p class="muted">Need someone new in your lineup?</p>${btn('Create a player first','add-player','','secondary')}`,'Register entrant');
}
function scoreSheet(id) {
  const m=s().matches.find(m=>m.id===id);if(m.scoring){openSheet('Live scoring','');scoringId=id;renderScoring(id);return;}
  formSheet('Start the game','start-score-form',`<input type="hidden" name="matchId" value="${id}"><p class="muted">Choose first service. The team cards stay in place throughout the game.</p>${picker('serving','First serving side',m.sides.map((e,i)=>({value:i,label:e.name})),0)}${m.sides[0].playerIds.length===2?m.sides.map((side,i)=>picker('right'+i,`${side.name} · starts on right`,side.playerIds.map((id,j)=>({value:j,label:player(s(),id)?.name})),0)).join(''):''}<div class="callout">Starting call: ${m.sides[0].playerIds.length===2?'0–0–2':'0–0'}. Traditional side-out scoring.</div>`,'Start scoring');
}
function renderScoring(id) {
  const m=s().matches.find(m=>m.id===id);if(!m?.scoring)return;
  const sc=m.scoring, server=m.sides[sc.serving].playerIds[sc.serverIndex], lastAction=document.activeElement?.dataset.action;
  dialog.className='scoring-sheet';
  document.querySelector('#sheet-content').innerHTML=`<div class="sheet-handle"></div><div class="sheet-head"><div><span class="eyebrow">${esc(s().courts.find(c=>c.id===m.courtId)?.name||'Game')} · ${esc(modes[m.mode])}</span><h2 id="sheet-title">${sc.winner!==null?'Game, set, good times.':'Make every rally count.'}</h2></div>${btn(icon('close'),'close','aria-label="Close scoring"','icon-btn quiet')}</div><div class="score-call" aria-live="polite"><span>${sc.winner!==null?'GAME COMPLETE':gamePoint(sc)?'GAME POINT · SCORE CALL':'SCORE CALL'}</span><strong>${esc(scoreCall(sc))}</strong><p>${sc.winner!==null?esc(m.sides[sc.winner].name)+' wins':`${esc(player(s(),server)?.name||m.sides[sc.serving].name)} serving · ${serviceCourt(sc)} court${sc.doubles?' · Server '+sc.server:''}`}</p></div><div class="score-teams">${m.sides.map((side,i)=>`<div class="score-team ${sc.serving===i?'is-serving':''}"><span class="score-team-label">SIDE ${i===0?'A':'B'} ${sc.serving===i?'· SERVING':''}</span><h3>${esc(side.name)}</h3><strong>${sc.points[i]}</strong></div>`).join('')}</div><p class="scoring-rule">To ${sc.target} · win by ${sc.margin} · Only the serving side scores</p><p class="form-error" role="alert"></p><div class="scoring-controls"><div class="rally-buttons">${m.sides.map((side,i)=>btn(`${icon('plus')}<span>${esc(side.name)}<small>won the rally</small></span>`,'rally',`data-id="${id}" data-side="${i}" ${sc.winner!==null?'disabled':''}`,`rally-btn side-${i}`)).join('')}</div><div class="row between">${btn(icon('undo')+' Undo rally','undo',`data-id="${id}" ${sc.history.length?'':'disabled'}`,'secondary')}${sc.winner!==null?btn('Save result','save-tracked',`data-id="${id}"`,'primary'):btn('Report final score','report',`data-id="${id}"`,'quiet')}</div><small class="muted">${sc.history.length} rallies saved · Closing this sheet keeps the live score.</small></div>`;
  if(lastAction)dialog.querySelector(`[data-action="${lastAction}"]`)?.focus({preventScroll:true});
}
function reportSheet(id, edit=false) {
  const m=s().matches.find(m=>m.id===id),points=m.result||m.scoring?.points||[0,0];
  formSheet(edit?'Correct a result':'Report final score','report-form',`<input type="hidden" name="matchId" value="${id}"><input type="hidden" name="edit" value="${edit}"><div class="form-grid">${stepper('a',m.sides[0].name,points[0],0,999)}${stepper('b',m.sides[1].name,points[1],0,999)}</div><p class="muted">To ${m.mode==='tournament'?s().tournament.target:11}, win by ${m.mode==='tournament'?s().tournament.margin:2}. A final score ends at the first winning point.</p>${m.mode==='open'?'<label class="checkbox"><input type="checkbox" name="requeue" checked> Return players to the back of the queue</label>':''}${edit?'<p class="callout">If a later match has a court or a result, release its court or clear its result first.</p>':''}`,'Save result',edit?btn('Clear result','clear-result',`data-id="${id}"`,'quiet'):'' );
}
async function shareSheet() {
  openSheet('Bring your people together',`<div class="sheet-form"><p>Session links expire after 12 hours and can be revoked by an organizer.</p><div class="share-options">${btn(icon('qr')+' Player check-in','create-invite','data-role="guest"','primary full')}${btn(icon('monitor')+' Read-only court display','create-invite','data-role="display"','secondary full')}</div><div id="share-result"></div><p class="form-error" role="alert"></p>${btn('Revoke all day-play/display links','revoke-invites','','quiet')}${!store.live?'<p class="callout">This link works in another tab of this browser. Use a connected account to invite people on other devices.</p>':''}</div>`);
}
async function doRun(command,payload={},message) { await store.run(command,payload);if(message)notify(message); }
function confirmSheet(title,message,action,attrs='') { openSheet(title,`<div class="sheet-form"><p>${message}</p><div class="sheet-footer">${btn('Keep playing','close','','secondary')}${btn('Confirm',action,attrs,'primary')}</div><p class="form-error" role="alert"></p></div>`); }
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target||!target.dataset.action||target.disabled)return;
  const action=target.dataset.action,id=target.dataset.id;
  try {
    if(action==='close'){closeSheet();return;}
    if(action==='demo'){location.href='club.html?explore=1';return;}
    if(action==='live'){location.href='./?live=1';return;}
    if(action==='account'){if(store.platformClub||store.role==='visitor'){location.href=`./${store.live?'?live=1':'?live=0'}#dashboard`;return;}if(!store.live){openSheet('Your clubhouse',`<div class="sheet-form"><p>Manage the courts, queue, and games from your clubhouse.</p>${btn('Open my account','live','','primary full')}<p class="muted">Sign in with an approved club account to access your clubs across devices.</p></div>`);}else if(organizer()){openSheet('Organizer account',`<div class="sheet-form"><p>Signed in as a club organizer.</p>${btn('Sign out','signout','','secondary')}</div>`);}else formSheet('Organizer sign in','signin-form',`${field('email','Email','email','','required autocomplete="username"')}${field('password','Password','password','','required autocomplete="current-password"')}`,'Sign in');return;}
    if(action==='signout'){await store.signOut();return;}
    if(action==='display'){if(store.role==='display')return;if(store.live)await shareSheet();else go('display');return;}
    if(!organizer()&&!action.startsWith('guest-'))throw new Error('Organizer access is required.');
    if(action==='settings'){settingsSheet();return;}
    if(action==='add-player'){addPlayerSheet();return;}
    if(action==='add-pair'){addPlayerSheet(true);return;}
    if(action==='join-existing'){checkInSheet();return;}
    if(action==='add-existing'){const id=dialog.querySelector('[name="existing"]').value, partnerId=dialog.querySelector('[name="existingPartner"]')?.value;if(mode==='tournament'){registerSheet();return;}await doRun(mode==='mixer'?'mixer-add':'join',mode==='mixer'?{playerId:id}:{mode:mode==='challenge'?'challenge':'open',playerIds:[id,partnerId].filter(Boolean)},'Player added');closeSheet();return;}
    if(action==='new-event'){eventSheet();return;}
    if(action==='register'){registerSheet();return;}
    if(action==='generate-tournament'){await doRun(action,{},'Matches generated');go('tournament','bracket');return;}
    if(action==='remove-entrant'){await doRun(action,{id});return;}
    if(action==='call-next'||action==='challenge-start'){await doRun(action,{courtId:target.dataset.court},'Group assigned to court');go(mode,'courts');return;}
    if(action==='call-selected'||action==='pair-selected'){const ids=[...document.querySelectorAll('[name="stackEntry"]:checked')].map(x=>x.value);await doRun(action==='pair-selected'?'pair-entries':'call-selected',{entryIds:ids},action==='pair-selected'?'Partners kept together':'Selected group called');if(action==='call-selected')go('open','courts');return;}
    if(action==='unpair'){await doRun('unpair-entry',{id});return;}
    if(action==='matching'){await doRun('settings',{matching:target.dataset.value});return;}
    if(action==='court-toggle'){await doRun('court-status',{id,status:target.dataset.status});return;}
    if(action==='queue-action'){await doRun(action,{id,mode:target.dataset.mode,action:target.dataset.value});return;}
    if(action==='ready-all'){const e=s().open.find(e=>e.id===id);for(const pid of e.playerIds)await doRun('ready',{id,playerId:pid});return;}
    if(action==='score'){scoreSheet(id);return;}
    if(action==='rally'||action==='undo'){await doRun(action,{matchId:id,side:Number(target.dataset.side)});return;}
    if(action==='save-tracked'){await doRun('save-result',{matchId:id},'Result saved');closeSheet();return;}
    if(action==='report'||action==='edit-score'){reportSheet(id,action==='edit-score');return;}
    if(action==='clear-result'){await doRun('edit-result',{matchId:id,result:null},'Result cleared');closeSheet();return;}
    if(action==='release'){confirmSheet('Release this court?','This cancels the call and returns players to their queue positions. Live scoring will be discarded.','confirm-release',`data-id="${id}"`);return;}
    if(action==='confirm-release'){await doRun('cancel-match',{matchId:id},'Court released');closeSheet();return;}
    if(action==='no-show'){const m=s().matches.find(m=>m.id===id);formSheet('Mark a no-show','no-show-form',`<input type="hidden" name="matchId" value="${id}">${picker('absent','Absent player',m.sides.flatMap(side=>side.playerIds).map(id=>({value:id,label:player(s(),id).name})))}<p>The absent player’s entry is paused. Other players return to their original queue positions.</p>`,'Cancel call');return;}
    if(action==='finish-without'){confirmSheet('Finish without a score?','The game will be recorded as unscored and the players will return to the back of the queue.','confirm-without',`data-id="${id}"`);return;}
    if(action==='confirm-without'){await doRun('save-result',{matchId:id,withoutScore:true},'Game completed');closeSheet();return;}
    if(action==='assign'){formSheet('Assign a court','assign-form',`<input type="hidden" name="matchId" value="${id}">${picker('courtId','Available court',s().courts.filter(c=>c.status==='available').map(c=>({value:c.id,label:c.name})))}<p class="muted">Courts occupied in any mode are unavailable.</p>`,'Assign court');return;}
    if(action==='mixer-round'){await doRun(action,{},'New mixer round started');go('mixer','courts');return;}
    if(action==='mixer-pause'){await doRun(action,{playerId:id});return;}
    if(action==='bracket-section'){bracketSection=target.dataset.value;round=1;render();return;}
    if(action==='round-next'||action==='round-prev'){round+=action==='round-next'?1:-1;render();return;}
    if(action==='share'){await shareSheet();return;}
    if(action==='create-invite'){
      target.disabled=true;const role=target.dataset.role,result=await store.invite(role);const url=new URL(location.href);url.search=`?${store.live?'live=1&':'live=0&'}${store.platformClub?'club='+store.clubId+'&':''}role=${role}&invite=${result.token}`;url.hash=role==='display'?'display/courts':'open/courts';
      const {toDataURL}=await import('../vendor/qrcode.js');const qr=await toDataURL(url.href,{width:280,margin:2,color:{dark:'#173f35',light:'#ffffff'}});
      document.querySelector('#share-result').innerHTML=`<div class="qr-result"><img src="${qr}" alt="QR code for ${role==='guest'?'player check-in':'read-only display'}" width="280" height="280"><p>${role==='guest'?'Scan to join this session':'Scan to open the court display'}</p><label for="invite-link">Session link</label><input id="invite-link" readonly value="${esc(url.href)}">${btn('Copy link','copy-link','','secondary')}<small>Expires ${formatDate(result.expires_at)}. Anyone with this link can ${role==='guest'?'check in':'view this session'}.</small></div>`;target.disabled=false;return;
    }
    if(action==='copy-link'){await navigator.clipboard.writeText(document.querySelector('#invite-link').value);notify('Link copied');return;}
    if(action==='revoke-invites'){await store.revokeInvites();notify('Session links revoked');closeSheet();return;}
    if(action==='clean-demo'){confirmSheet('Remove starter records?','Release active starter games first. This removes preloaded players, their queues, events and games. Players you added are kept.','confirm-clean');return;}
    if(action==='confirm-clean'){await doRun('clean-demo',{},'Starter records removed');closeSheet();return;}
    if(action==='reset-demo'){confirmSheet('Restore the clubhouse?','This replaces the clubhouse saved in this browser with the original roster and games.','confirm-reset');return;}
    if(action==='confirm-reset'){await store.resetDemo();closeSheet();notify('Clubhouse restored');return;}
    if(action==='guest-ready'){await store.guest('ready',{});notify('You’re ready');return;}
    if(action==='guest-pause'){await store.guest('toggle-pause',{});return;}
    if(action==='guest-leave'){await store.guest('leave',{});return;}
  } catch(error) {showError(error);target.disabled=false;}
});
function showError(error) { const el=dialog.open?dialog.querySelector('.form-error'):document.querySelector('.form-error');if(el){el.textContent=error.message;el.tabIndex=-1;el.focus();}else notify(error.message,true); }
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target, data=Object.fromEntries(new FormData(form)), submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
  try {
    if(form.id==='signin-form'){await store.signIn(data.email,data.password);return;}
    if(form.id==='guest-form'){await store.guest('join',{name:data.name,skill:data.skill,partner:data.partner||''});return;}
    if(form.id==='add-player-form'){
      // One logical mutation keeps a new player and their check-in together.
      await doRun('register-and-join',{name:data.name,skill:data.skill,partner:data.partner||'',team:data.team,mode:data.mode},'Player added');
    }
    if(form.id==='join-form')await doRun('join',{mode:data.mode,playerIds:[data.first,data.second].filter(Boolean)},'Players checked in');
    if(form.id==='settings-form')await doRun('settings',data,'Settings saved');
    if(form.id==='event-form'){await doRun('new-tournament',{...data,confirm:!!data.confirm},'Tournament created');go('tournament','entries');}
    if(form.id==='register-form')await doRun('register-entrant',{name:data.name,playerIds:[data.first,data.second].filter(Boolean)},'Entrant registered');
    if(form.id==='start-score-form'){await doRun('start-score',{matchId:data.matchId,serving:Number(data.serving),right:[Number(data.right0||0),Number(data.right1||0)]});scoringId=data.matchId;renderScoring(data.matchId);return;}
    if(form.id==='report-form')await doRun(data.edit==='true'?'edit-result':'save-result',{matchId:data.matchId,result:[Number(data.a),Number(data.b)],requeue:!!data.requeue},'Result saved');
    if(form.id==='assign-form')await doRun('assign-match',{matchId:data.matchId,courtId:data.courtId},'Court assigned');
    if(form.id==='no-show-form')await doRun('cancel-match',{matchId:data.matchId,absentId:data.absent},'Call cancelled; no-show paused');
    closeSheet();
  }catch(error){showError(error);}finally{if(submit)submit.disabled=false;}
});
setupComponents();
dialog.addEventListener('cancel',()=>{scoringId=null;document.body.classList.remove('modal-open');});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
window.addEventListener('hashchange',readRoute);
store.addEventListener('change',render);
try {await store.init();readRoute();}catch(error){store.status='Setup needed';renderHeader();main.innerHTML=`<section class="welcome"><h1>Let’s connect your clubhouse.</h1><p class="error">${esc(error.message)}</p><p>We couldn’t load this club. Try again or contact your club owner for help.</p>${btn('Try again','reload','','primary')}${btn('Explore the clubhouse','demo','','secondary')}${btn('Organizer sign in','account','','quiet')}</section>`;document.querySelector('[data-action="reload"]')?.addEventListener('click',()=>location.reload());}
